-- CA-22: Update to show Valadao (R) confirmed, Dem 2nd spot still uncalled (Villegas vs Bains)
UPDATE house_races SET candidate2_name = 'David G. Valadao', candidate2_party = 'R', candidate1_name = 'TBD — Dem: Villegas vs Bains (counting)' WHERE state_code = 'CA' AND district = '22';

